param()
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$root='F:\study\codex\Project-Limitless\Temp\DiscordUsageDiagnostics20261026\Worktree'
$dir=Join-Path $root 'Tools/DiscordAIServiceDiagnostics/TokenIsolationPreparation';Add-Type -Path (Join-Path $dir 'IsolationModel.cs')
function Valid-Gates {$g=[Limitless.TokenIsolationPreparation.Gates]::new();foreach($p in $g.GetType().GetFields()){$p.SetValue($g,$true)};return $g}
$script:rows=@();function Check-Isolation($Name,[scriptblock]$Test){try{if(-not (& $Test)){throw 'ASSERT'};$script:rows+=@{name=$Name;status='PASS'}}catch{$script:rows+=@{name=$Name;status='FAIL';type=$_.Exception.GetType().FullName}}}
Check-Isolation 'NORMAL_MODEL_OWNED_CLEANUP_AND_INTENT_BEFORE_LOGON' {$r=[Limitless.TokenIsolationPreparation.IsolationModel]::Simulate((Valid-Gates),'');$r.Status -eq 'OFFLINE_MODEL_COMPLETED_NOT_WINDOWS_VERIFIED' -and $r.Trace[0] -eq 'INTENT_NEW_TRIAL_ONLY' -and $r.PeakProcesses -eq 1 -and $r.FakeOpenHandles -eq 0 -and $r.FakeActiveProcesses -eq 0 -and $r.FinalEvidence -and -not $r.NativeExecuted}
foreach($field in [Limitless.TokenIsolationPreparation.Gates].GetFields()){Check-Isolation ('PRELOGON_HOLD_'+$field.Name) {$g=Valid-Gates;$field.SetValue($g,$false);$r=[Limitless.TokenIsolationPreparation.IsolationModel]::Simulate($g,'');$r.Status -eq 'HOLD' -and $r.FakeLogons -eq 0 -and $r.FakeProcesses -eq 0}}
foreach($fault in @('JOURNAL_FAILURE','JOB_READBACK_FAILURE','LOGON_FAILURE','SESSION_NOT_ZERO','WRONG_SID','PRIVILEGE_MISSING','CREATE_READBACK_FAILURE','PID_REUSE','TOKEN_MUTATION','CANCEL','ACCESSCHECK_FAILURE','TIMEOUT','CHILD_ATTEMPT')){Check-Isolation ('FAULT_CLEANUP_'+$fault) {$r=[Limitless.TokenIsolationPreparation.IsolationModel]::Simulate((Valid-Gates),$fault);$r.Status -eq 'HOLD' -and $r.FakeActiveProcesses -eq 0 -and $r.FakeOpenHandles -eq 0 -and $r.PeakProcesses -le 1}}
Check-Isolation 'WINDOW_CLOSE_KERNEL_KILL_NO_FINALLY_EVIDENCE_CLAIM' {$r=[Limitless.TokenIsolationPreparation.IsolationModel]::Simulate((Valid-Gates),'WINDOW_CLOSE');$r.KernelCloseOnly -and -not $r.FinalEvidence -and $r.DurableIntent -and $r.FakeActiveProcesses -eq 0 -and -not $r.Trace.Contains('TERMINATE_ONLY_OWN_JOB')}
Check-Isolation 'MONOTONIC_WALL_BUDGET_NOT_JOB_CPU_LIMIT' {$r=[Limitless.TokenIsolationPreparation.IsolationModel]::Simulate((Valid-Gates),'TIMEOUT');$r.WorkerTerminateDeadlineSeconds -eq 85 -and $r.OverallDeadlineSeconds -eq 90}
Check-Isolation 'UNCONFIRMED_CLEANUP_IS_UNKNOWN' {$r=[Limitless.TokenIsolationPreparation.IsolationModel]::Simulate((Valid-Gates),'CLEANUP_UNCONFIRMED');$r.Status -eq 'HOLD' -and $r.FakeOpenHandles -eq -1 -and $r.FakeActiveProcesses -eq -1}
Check-Isolation 'FINAL_EVIDENCE_FAILURE_HOLD_NO_RETRY' {$r=[Limitless.TokenIsolationPreparation.IsolationModel]::Simulate((Valid-Gates),'FINAL_JOURNAL_FAILURE');$r.Status -eq 'HOLD' -and -not $r.FinalEvidence}
Check-Isolation 'RUN_BRANCH_CANNOT_EXECUTE_WINDOWS' {$source=[IO.File]::ReadAllText((Join-Path $dir 'inspect-isolation-plan.ps1'));$r=& ([scriptblock]::Create($source)) -Action Run|ConvertFrom-Json;$r.status -eq 'HOLD_ACTUAL_EXECUTION_NOT_IMPLEMENTED_OR_AUTHORIZED' -and $r.new_logons -eq 0 -and $r.worker_processes_created -eq 0}
@{kind='SID1010_ISOLATION_OFFLINE_MODEL';pass=@($script:rows|Where-Object status -EQ PASS).Count;fail=@($script:rows|Where-Object status -EQ FAIL).Count;tests=$script:rows;actual_logons=0;actual_worker_processes=0;actual_jobs=0;actual_tokens=0;existing_pass_tests_repeated=$false}|ConvertTo-Json -Depth 8
